<?php require 'page-guard.php';require '../config/db_conn.php';$id=(int)($_POST['id']??0);$name=trim($_POST['teacher_name']??'');$section=trim($_POST['section']??'');$current=$_POST['current_password']??'';$pass=$_POST['teacher_pass']??'';$confirm=$_POST['teacher_confirm']??'';if(!$id||$name===''||$section==='')exit('Invalid teacher details.');$find=$conn->prepare('SELECT TEACHER_PASS FROM teachers WHERE TEACHER_ID=?');$find->bind_param('i',$id);$find->execute();$existing=$find->get_result()->fetch_assoc();if($pass!==''||$current!==''){if(!$existing||!password_verify($current,$existing['TEACHER_PASS'])||strlen($pass)<8||$pass!==$confirm)exit('Current password is incorrect or the new passwords do not match.');$hash=password_hash($pass,PASSWORD_DEFAULT);$stmt=$conn->prepare('UPDATE teachers SET TEACHER_NAME=?,SECTION=?,TEACHER_PASS=? WHERE TEACHER_ID=?');$stmt->bind_param('sssi',$name,$section,$hash,$id);}else{$stmt=$conn->prepare('UPDATE teachers SET TEACHER_NAME=?,SECTION=? WHERE TEACHER_ID=?');$stmt->bind_param('ssi',$name,$section,$id);}$stmt->execute();$_SESSION['toast']=['message'=>'Teacher profile updated successfully.','type'=>'success'];header('Location: edit-teacher.php?id='.$id);exit;
